const app = document.querySelector('#app');
const state = { token: localStorage.getItem('aith_token'), data: null, page: 'dashboard', modal: null, toast: null, aiTask: 'test_cases', aiResult: '', caseQuery: { projectId: '', module: '', caseType: '' }, pages: {} };
const navItems = [['dashboard','总览','◈','project:read'],['projects','项目空间','◇','project:read'],['cases','测试用例','☷','case:read'],['plans','测试计划','✓','plan:read'],['ui','UI 自动化','⌘','ui:read'],['defects','缺陷追踪','◉','defect:read'],['reports','质量报告','▤','report:read'],['ai','AI 工作台','✦','ai:use'],['tokens','访问令牌','⌁','token:manage'],['users','用户与权限','♙','user:manage'],['settings','AI 设置','⚙','ai:manage'],['security','账号安全','⊙','project:read']];
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const can = (p) => state.data?.permissions?.includes('*') || state.data?.permissions?.includes(p);
const project = (id) => state.data?.projects?.find((x) => x.id === id)?.name || '未分配项目';
const user = (id) => state.data?.users?.find((x) => x.id === id)?.displayName || '未分配';
const fmt = (date) => date ? new Date(date).toLocaleString('zh-CN',{hour12:false}) : '-';
const badge = (label, tone='') => '<span class="badge '+tone+'">'+esc(label)+'</span>';
const status = (v) => ({passed:badge('通过','green'),failed:badge('失败','red'),blocked:badge('阻塞','amber'),queued:badge('排队中','blue'),open:badge('待修复','red'),in_progress:badge('修复中','amber'),resolved:badge('已修复'),verified:badge('已验证','green'),closed:badge('已关闭','green'),active:badge('进行中','green'),draft:badge('草稿')}[v] || badge(v));
class ApiError extends Error { constructor(message, meta={}) { super(message); Object.assign(this,meta); } }
async function api(path, options={}) { const headers={...(options.body?{'Content-Type':'application/json'}:{}),...(state.token?{Authorization:'Bearer '+state.token}:{}),...options.headers}; let res, data={}; try { res=await fetch('/api'+path,{...options,headers,body:options.body&&typeof options.body!=='string'?JSON.stringify(options.body):options.body}); data=await res.json().catch(()=>({})); } catch { throw new ApiError('无法连接服务，请确认本地服务正在运行。',{code:'network_error'}); } if(!res.ok) throw new ApiError(data.error?.message || '请求失败',{code:data.error?.code||'http_'+res.status,requestId:data.error?.requestId,details:data.error?.details}); return data; }
async function refresh(){ state.data=await api('/bootstrap'); render(); }
function notify(message, kind='success'){ state.toast={message,kind}; render(); clearTimeout(window.__aithToast); window.__aithToast=setTimeout(()=>{state.toast=null;render();}, kind==='error'?4200:2600); }
function pageTitle(title,sub,action=''){ return '<section class="page-title"><div><span class="eyebrow">AI–TESTHUB / WORKSPACE</span><h1>'+title+'</h1><p>'+sub+'</p></div>'+action+'</section>'; }
function layout(content){ const nav=navItems.filter(([, , ,p])=>can(p)).map(([id,label,icon])=>'<button data-page="'+id+'" class="'+(state.page===id?'active':'')+'"><i>'+icon+'</i>'+label+'</button>').join(''); const ctx=state.data.tokenContext; app.innerHTML='<div class="shell"><aside class="sidebar"><div class="side-logo"><span>AI</span><b>TestHub</b></div><div class="side-caption">QUALITY COMMAND CENTER</div><nav class="nav">'+nav+'</nav><div class="side-footer"><div class="pulse"></div><span>系统在线 · SQLite</span></div></aside><section class="content"><header class="topbar"><div class="command-dot"></div><span>质量工程控制台</span><div class="top-actions">'+(ctx?.kind==='api'?badge('API '+ctx.level,'amber'):'')+badge(state.data.user.roleName,'blue')+'<div class="account-wrap"><button class="account" data-action="toggle-account-menu" title="账户菜单" aria-label="账户菜单"><span>'+esc(state.data.user.displayName).slice(0,1)+'</span></button><div class="account-menu"><div class="account-menu-head"><b>'+esc(state.data.user.displayName)+'</b><small>'+esc(state.data.user.roleName)+'</small></div><button data-action="logout"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 5H5v14h5M14 8l4 4-4 4M18 12H9"/></svg>退出系统</button></div></div></div></header><main class="page">'+content+'</main></section></div>'+(state.modal||'')+(state.toast?'<div class="toast '+state.toast.kind+'"><b>'+ (state.toast.kind==='error'?'操作失败':'已完成')+'</b><span>'+esc(state.toast.message)+'</span></div>':''); bind(); }
function dashboard(){ const s=state.data.summary, e=s.executions; return pageTitle('质量总览','实时追踪测试资产、自动化覆盖与发布风险','<button class="btn glow" data-modal="execution" data-action="modal">快速执行</button>')+'<div class="hero"><div><span>RELEASE READINESS</span><strong>'+e.passRate+'<em>%</em></strong><p>当前版本测试通过率 · '+e.passed+' 通过 / '+e.total+' 已执行</p></div><div class="hero-orb"></div><div class="hero-meta"><b>'+s.defects.open+'</b><small>未关闭缺陷</small><b>'+state.data.uiCases.length+'</b><small>UI 自动化脚本</small></div></div><div class="metrics"><div class="metric"><small>活跃项目</small><b>'+state.data.projects.length+'</b><span>协作空间</span></div><div class="metric"><small>测试用例</small><b>'+s.cases+'</b><span>可复用资产</span></div><div class="metric"><small>自动化覆盖</small><b>'+state.data.uiCases.length+'</b><span>Playwright 脚本</span></div><div class="metric"><small>高风险项</small><b>'+s.risks.length+'</b><span>需要优先处理</span></div></div><div class="split"><section class="card panel"><h3>执行信号</h3>'+bar('通过',e.passed,e.total,'ok')+bar('失败',e.failed,e.total,'fail')+bar('阻塞',e.blocked,e.total,'warn')+'</section><section class="card panel"><h3>发布风险</h3>'+(s.risks.map(r=>'<div class="risk"><span></span><div><b>'+esc(r.title)+'</b><small>'+esc(r.severity)+' · '+esc(r.status)+'</small></div></div>').join('')||'<p class="muted">暂无高风险项</p>')+'</section></div>'; }
function bar(n,v,t,c){return '<div class="bar-row"><span>'+n+'</span><div><i class="'+c+'" style="width:'+(t?Math.round(v/t*100):0)+'%"></i></div><b>'+v+'</b></div>';}
function table(headers, rows, empty='暂无数据', key='default'){const items=Array.isArray(rows)?rows:(typeof rows==='string'?(rows.match(/<tr>[\s\S]*?<\/tr>/g)||[]):[]);const pageSize=10,total=items.length,totalPages=Math.max(1,Math.ceil(total/pageSize)),page=Math.min(state.pages[key]||1,totalPages),slice=items.slice((page-1)*pageSize,page*pageSize);state.pages[key]=page;const body=slice.length?slice.join(''):'<tr><td colspan="'+headers.length+'" class="empty">'+empty+'</td></tr>';const pagination=total>pageSize?'<footer class="pagination"><span>共 '+total+' 条 · 第 '+page+' / '+totalPages+' 页</span><div><button class="btn ghost small" data-action="page-table" data-page-key="'+key+'" data-page-target="'+(page-1)+'" '+(page===1?'disabled':'')+'>上一页</button><button class="btn ghost small" data-action="page-table" data-page-key="'+key+'" data-page-target="'+(page+1)+'" '+(page===totalPages?'disabled':'')+'>下一页</button></div></footer>':'';return '<section class="card table-card"><table class="data-table"><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table>'+pagination+'</section>';}
function projects(){const rows=state.data.projects.map(p=>'<tr><td><b>'+esc(p.name)+'</b><small>'+esc(p.description||'暂无说明')+'</small></td><td class="mono">'+esc(p.code)+'</td><td>'+p.members.length+' 位成员</td><td>'+status(p.status)+'</td><td>'+fmt(p.createdAt)+'</td><td>'+ (can('project:write')?'<button class="link" data-action="edit-project" data-id="'+p.id+'">编辑</button>':'—')+'</td></tr>');return pageTitle('项目空间','配置项目边界、成员与测试资产',can('project:write')?'<button class="btn glow" data-action="modal" data-modal="project">新建项目</button>':'')+table(['项目','编码','成员','状态','创建时间','操作'],rows,'暂无项目','projects');}
function caseTypeName(type){return ({functional:'功能',api:'接口',ui:'UI',performance:'性能',security:'安全',compatibility:'兼容性'})[type]||'功能';}
function getCaseFilters(){return {projectId:document.querySelector('[data-case-project]')?.value||'',module:document.querySelector('[data-case-module]')?.value||'',caseType:document.querySelector('[data-case-type]')?.value||''};}
function filteredCases(){const q=state.caseQuery;return state.data.cases.filter(c=>(!q.projectId||c.projectId===q.projectId)&&(!q.module||c.module===q.module)&&(!q.caseType||c.caseType===q.caseType));}
function caseRows(list){return list.map(c=>'<tr><td><b>'+esc(c.title)+'</b><small>'+esc(c.module)+' · '+c.steps.length+' 个步骤</small></td><td>'+esc(project(c.projectId))+'</td><td>'+badge(caseTypeName(c.caseType),'blue')+'</td><td>'+badge(c.priority,c.priority==='P0'?'red':'amber')+'</td><td>'+c.tags.map(x=>badge(x)).join(' ')+'</td><td>'+(can('case:write')?'<button class="link" data-action="edit-case" data-id="'+c.id+'">编辑</button>':'只读')+'</td></tr>').join('');}
function cases(){const caseTypes=['functional','api','ui','performance','security','compatibility'];const modules=[...new Set(state.data.cases.map(c=>c.module))];const q=state.caseQuery;const list=filteredCases();const actions=can('case:write')?'<div class="page-actions"><button class="btn" data-action="export-cases">导出 Excel</button><button class="btn" data-action="modal" data-modal="case-import">导入用例</button><button class="btn glow" data-action="modal" data-modal="case">新建用例</button></div>':'<button class="btn" data-action="export-cases">导出 Excel</button>';return pageTitle('测试用例','按项目、模块和用例类型精确查询；导入上限 1000 条',actions)+'<section class="case-query card"><div class="query-title"><span>筛选条件</span><small>设置条件后点击查询生效</small></div><div class="query-fields"><label>项目<select data-case-project><option value="">全部项目</option>'+state.data.projects.map(p=>'<option value="'+p.id+'" '+(q.projectId===p.id?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><label>模块<select data-case-module><option value="">全部模块</option>'+modules.map(m=>'<option value="'+esc(m)+'" '+(q.module===m?'selected':'')+'>'+esc(m)+'</option>').join('')+'</select></label><label>用例类型<select data-case-type><option value="">全部类型</option>'+caseTypes.map(t=>'<option value="'+t+'" '+(q.caseType===t?'selected':'')+'>'+caseTypeName(t)+'</option>').join('')+'</select></label><div class="query-actions"><button class="btn glow" data-action="query-cases">查询</button><button class="btn ghost" data-action="reset-case-query">重置</button></div></div></section><div class="result-strip"><b>查询结果</b><span>共 <strong data-case-count>'+list.length+'</strong> 条测试用例</span></div><div data-case-table>'+table(['用例','项目','类型','优先级','标签','操作'],caseRows(list).match(/<tr>[\s\S]*?<\/tr>/g)||[],'没有匹配的测试用例，请调整条件后重新查询','cases')+'</div>';}
function plans(){const rows=state.data.plans.map(p=>'<tr><td><b>'+esc(p.name)+'</b><small>'+esc(p.version||'未设置版本')+'</small></td><td>'+esc(project(p.projectId))+'</td><td>'+p.executions.length+' / '+p.caseIds.length+'</td><td>'+status(p.status)+'</td><td><button class="link" data-action="execute" data-id="'+p.id+'">执行</button></td></tr>');return pageTitle('测试计划','组织回归、冒烟与版本验证',can('plan:write')?'<button class="btn glow" data-action="modal" data-modal="plan">创建计划</button>':'')+table(['计划','项目','进度','状态','操作'],rows,'暂无测试计划','plans');}
function ui(){ const rows=state.data.uiCases.map(c=>{const last=c.runs?.[0];return '<tr><td><b>'+esc(c.name)+'</b><small>'+esc(c.environment)+' · '+esc(c.browser)+'</small></td><td>'+esc(project(c.projectId))+'</td><td>'+c.tags.map(x=>badge(x)).join(' ')+'</td><td>'+ (last?status(last.status)+' <small>'+last.duration+'s</small>':'未运行')+'</td><td><div class="row-actions">'+(can('ui:execute')?'<button class="link" data-action="run-ui" data-id="'+c.id+'">运行</button>':'')+(can('ui:write')?'<button class="link" data-action="edit-ui" data-id="'+c.id+'">编辑</button>':'')+'</div></td></tr>';}); return pageTitle('UI 自动化','基于 Playwright 的脚本资产与受控执行记录',can('ui:write')?'<button class="btn glow" data-action="modal" data-modal="ui">新建 UI 脚本</button>':'')+'<div class="automation-banner"><div><span>PLAYWRIGHT / CONTROLLED RUNNER</span><b>安全自动化，从脚本资产到执行可追溯</b><p>当前版本只创建与调度记录，不在 Web 进程中执行任意用户代码。接入隔离 Runner 后可安全运行。</p></div><div class="browser-dots"><i></i><i></i><i></i></div></div>'+table(['脚本','项目','标签','最近执行','操作'],rows,'暂无 UI 自动化脚本，创建第一条 Playwright 脚本吧。','ui');}
function defects(){const rows=state.data.defects.map(d=>'<tr><td><b>'+esc(d.title)+'</b><small>'+esc(d.description.slice(0,72))+'</small></td><td>'+esc(project(d.projectId))+'</td><td>'+badge(d.severity,d.severity==='major'||d.severity==='critical'?'red':'amber')+' '+badge(d.priority)+'</td><td>'+esc(user(d.assigneeId))+'</td><td>'+status(d.status)+'</td><td>'+ (can('defect:write')?'<button class="link" data-action="edit-defect" data-id="'+d.id+'">更新</button>':'—')+'</td></tr>');return pageTitle('缺陷追踪','关联测试结果，形成修复验证闭环',can('defect:write')?'<button class="btn glow" data-action="modal" data-modal="defect">提交缺陷</button>':'')+table(['缺陷','项目','级别','处理人','状态','操作'],rows,'暂无缺陷','defects');}
function reports(){const s=state.data.summary,c=s.coverage,e=s.executions,gate=s.release;const total=e.total||1;const bar=(label,value,tone)=>'<div class="report-bar"><span>'+label+'</span><i><b class="'+tone+'" style="width:'+Math.round(value/total*100)+'%"></b></i><strong>'+value+'</strong></div>';const risks=s.risks.map(r=>'<li><span class="risk-dot '+esc(r.severity)+'"></span><div><b>'+esc(r.title)+'</b><small>'+esc(r.severity)+' · '+esc(r.priority)+' · '+esc(r.status)+'</small></div></li>').join('')||'<li class="report-empty">当前没有待处理的高风险缺陷</li>';return pageTitle('质量报告','从覆盖、执行、缺陷到发布门禁，一屏查看质量结论',can('report:export')?'<button class="btn glow" data-action="export">导出精美报告</button>':'')+'<section class="quality-hero '+gate.status+'"><div><span>RELEASE QUALITY GATE</span><h2>'+esc(gate.label)+'</h2><p>'+esc(gate.detail)+'</p></div><div class="quality-ring"><b>'+e.passRate+'%</b><small>执行通过率</small></div></section><div class="quality-kpis"><article><small>测试覆盖率</small><b>'+c.rate+'%</b><span>'+c.executed+' / '+c.total+' 条用例已执行</span></article><article><small>执行结果</small><b>'+e.total+'</b><span>通过 '+e.passed+' · 失败 '+e.failed+' · 阻塞 '+e.blocked+'</span></article><article><small>未关闭缺陷</small><b>'+s.defects.open+'</b><span>致命 '+s.defects.critical+' · 严重 '+s.defects.major+'</span></article><article><small>冒烟完成度</small><b>'+(s.smoke.total?Math.round(s.smoke.executed/s.smoke.total*100):0)+'%</b><span>'+s.smoke.executed+' / '+s.smoke.total+' 条已执行</span></article></div><div class="report-layout"><section class="card report-panel"><header><div><span class="eyebrow">EXECUTION HEALTH</span><h3>执行结果分布</h3></div><small>共 '+e.total+' 条执行记录</small></header><div class="report-bars">'+bar('通过',e.passed,'pass')+bar('失败',e.failed,'fail')+bar('阻塞',e.blocked,'block')+bar('跳过',e.skipped,'skip')+'</div><div class="coverage-track"><div><span>测试覆盖进度</span><b>'+c.rate+'%</b></div><i><b style="width:'+c.rate+'%"></b></i><small>尚有 '+c.unexecuted+' 条测试用例未执行</small></div></section><section class="card report-panel risk-panel"><header><div><span class="eyebrow">RELEASE RISKS</span><h3>发布风险清单</h3></div><small>'+s.risks.length+' 项</small></header><ul>'+risks+'</ul></section></div>';}
function ai(){const title={test_cases:'智能用例生成',defect_analysis:'缺陷根因分析',report_summary:'测试报告摘要'};return pageTitle('AI 工作台','选择模型后，将质量数据转化为可执行洞察')+'<div class="ai-layout"><section class="card ai-nav">'+Object.entries(title).map(([k,v])=>'<button data-action="ai-task" data-task="'+k+'" class="'+(k===state.aiTask?'active':'')+'">✦ <b>'+v+'</b></button>').join('')+'</section><section class="card panel"><h3>'+title[state.aiTask]+'</h3><form data-form="ai"><label>输入上下文<textarea name="input" placeholder="粘贴需求、缺陷现象或补充说明…"></textarea></label><button class="btn glow" '+(!state.data.aiConfigs?.length?'disabled':'')+'>生成分析</button></form><pre class="ai-result">'+esc(state.aiResult||'配置 AI 模型后，在这里获得可追溯的测试洞察。')+'</pre></section></div>';}
function tokens(){const list=state.data.apiTokens||[];const rows=list.map(t=>'<tr><td><b>'+esc(t.name)+'</b><small class="mono">'+esc(t.prefix)+'••••</small></td><td>'+badge(t.level,t.level==='admin'?'red':t.level==='write'?'amber':'blue')+'</td><td>'+ (t.projectIds?.length?t.projectIds.map(project).join('、'):'全部项目')+'</td><td>'+fmt(t.lastUsedAt)+'</td><td>'+ (t.revokedAt?badge('已撤销','red'):'有效')+'</td><td>'+(!t.revokedAt?'<button class="link danger" data-action="revoke-token" data-id="'+t.id+'">撤销</button>':'—')+'</td></tr>').join('');return pageTitle('访问令牌','令牌权限在角色权限之外再次收敛；密钥只在创建时显示一次','<button class="btn glow" data-action="modal" data-modal="token">创建令牌</button>')+'<div class="token-guide"><div>'+badge('read','blue')+' 仅可读取已授权项目</div><div>'+badge('write','amber')+' 可读写项目测试资产，但不能管理系统</div><div>'+badge('admin','red')+' 受创建者角色约束的管理级调用</div></div>'+table(['令牌','级别','项目范围','最近使用','状态','操作'],rows,'暂无访问令牌');}
function users(){return pageTitle('用户与权限','角色权限、令牌范围与高敏感密码操作均由服务端校验','<button class="btn glow" data-action="modal" data-modal="user">新增用户</button>')+table(['用户','角色','2FA','状态','密码状态','高敏感操作'],state.data.users.map(u=>'<tr><td><b>'+esc(u.displayName)+'</b><small>'+esc(u.username)+'</small></td><td>'+badge(u.roleName,'blue')+'</td><td>'+ (u.twoFactorEnabled?badge('已启用','green'):badge('未启用','amber'))+'</td><td>'+badge(u.active?'正常':'停用',u.active?'green':'red')+'</td><td>'+badge('已设置','green')+'<small>仅可重置，不可查看</small></td><td><button class="link" data-action="change-password" data-id="'+u.id+'">重置密码</button></td></tr>').join(''));}
function settings(){const rows=(state.data.aiConfigs||[]).map(c=>'<tr><td><b>'+esc(c.name)+'</b></td><td>'+esc(c.provider)+'</td><td class="mono">'+esc(c.model)+'</td><td>'+badge(c.enabled?'默认':'备用',c.enabled?'green':'')+'</td></tr>').join('');return pageTitle('AI 设置','API Key 在服务端加密存储，永不返回浏览器', '<button class="btn glow" data-action="modal" data-modal="ai-config">添加模型</button>')+table(['名称','提供商','模型','状态'],rows,'暂无模型配置')+'<section class="card panel"><h3>存储状态</h3><p class="muted">SQLite · <code>data/ai-testhub.db</code>。无需额外数据库服务。</p></section>';}
function security(){return pageTitle('账号安全','登录会话 8 小时有效，支持 TOTP 双因素认证')+'<section class="card panel security"><h3>双因素认证</h3><p>保护管理权限和 AI 配置。启用后登录必须提供验证器中的 6 位动态码。</p>'+(state.data.user.twoFactorEnabled?'<button class="btn danger" data-action="disable-2fa">关闭 2FA</button>':'<button class="btn glow" data-action="setup-2fa">启用 2FA</button>')+'</section>';}
function render(){if(!state.data)return login();const pages={dashboard,projects,cases,plans,ui,defects,reports,ai,tokens,users,settings,security};layout((pages[state.page]||dashboard)());}
function login(){app.innerHTML='<div class="login-shell"><section class="brand-pane"><div class="brand-grid"></div><span class="brand-mark">AI</span><span class="eyebrow">QUALITY INTELLIGENCE PLATFORM</span><h1>Ship quality.<br><i>With confidence.</i></h1><p>从测试资产、自动化执行到 AI 风险洞察，构建团队的质量中枢。</p><div class="login-points"><span>◈ 多层 RBAC 与令牌范围</span><span>⌘ Playwright UI 自动化</span><span>✦ AI 测试工作台</span></div></section><section class="login-pane"><form class="login-card" data-form="login"><span class="eyebrow">WELCOME BACK</span><h2>进入质量中枢</h2><label>用户名<input name="username" required value="admin"></label><label>密码<div class="password-field"><input name="password" type="password" required><button type="button" class="eye-btn" data-action="toggle-password" aria-label="显示密码" title="显示密码"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.3 12s3.5-6 9.7-6 9.7 6 9.7 6-3.5 6-9.7 6-9.7-6-9.7-6Z"/><circle cx="12" cy="12" r="2.8"/></svg></button></div></label><label>动态验证码 <small>启用 2FA 后必填</small><input name="otp" inputmode="numeric" maxlength="6" placeholder="6 位验证码"></label><button class="btn glow wide">登录</button></form></section></div>'+(state.toast?'<div class="toast '+state.toast.kind+'"><b>登录失败</b><span>'+esc(state.toast.message)+'</span></div>':'');bind();}
function options(selected){return state.data.projects.map(p=>'<option value="'+p.id+'" '+(p.id===selected?'selected':'')+'>'+esc(p.name)+'</option>').join('');}
function checks(selected=[]){return '<div class="member-checks">'+state.data.users.map(u=>'<label><input type="checkbox" name="memberIds" value="'+u.id+'" '+(selected.includes(u.id)?'checked':'')+'><span>'+esc(u.displayName)+'</span><small>'+esc(u.roleName)+'</small></label>').join('')+'</div>';}
function modal(type,obj){let title='',body='';const close='<button class="icon-btn" data-action="close">×</button>';if(type==='project'){title=obj?'编辑项目':'创建项目';body='<form data-form="project" data-id="'+(obj?.id||'')+'"><div class="form-grid"><label>项目名称<input name="name" required value="'+esc(obj?.name||'')+'"></label><label>项目编码<input name="code" required value="'+esc(obj?.code||'')+'"></label><label class="full">项目说明<textarea name="description">'+esc(obj?.description||'')+'</textarea></label><label>状态<select name="status"><option value="active">进行中</option><option value="archived">已归档</option></select></label><div class="full"><span class="field-label">项目成员</span>'+checks(obj?.members||[])+'</div></div><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">保存项目</button></footer></form>';}if(type==='case-import'){title='批量导入测试用例';body='<form data-form="case-import"><div class="import-guide"><div><b>导入规则</b><ul><li>仅支持 UTF-8 编码的 CSV 文件</li><li>单次最多导入 <strong>1000</strong> 条</li><li>项目 ID 必须与系统项目一致；当前 Token 必须有该项目写入权限</li></ul></div><a class="link" href="/templates/test-cases-template.csv" download>下载 CSV 模板</a></div><div class="field-list"><b>必填列</b><code>title, projectId, module, caseType, priority, tags, precondition, steps</code><small>caseType：functional / api / ui / performance / security / compatibility；steps 格式：操作 | 预期</small></div><label class="import-dropzone" data-import-zone><input id="case-import-file" type="file" accept=".csv,text/csv" required><span class="upload-icon">⇧</span><b>点击或拖拽上传 CSV 文件</b><small data-import-name>请使用上方模板，系统将校验字段与行数</small></label><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">确认导入</button></footer></form>';}if(type==='case'){title=obj?'编辑用例':'新建用例';const steps=obj?.steps?.map(x=>x.action+' | '+x.expected).join('\n')||'';body='<form data-form="case" data-id="'+(obj?.id||'')+'"><div class="form-grid"><label>项目<select name="projectId">'+options(obj?.projectId)+'</select></label><label>优先级<select name="priority">'+['P0','P1','P2','P3'].map(x=>'<option '+(obj?.priority===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label>用例类型<select name="caseType">'+['functional','api','ui','performance','security','compatibility'].map(t=>'<option value="'+t+'" '+(obj?.caseType===t?'selected':'')+'>'+caseTypeName(t)+'</option>').join('')+'</select></label><label class="full">标题<input name="title" required value="'+esc(obj?.title||'')+'"></label><label>模块<input name="module" value="'+esc(obj?.module||'')+'"></label><label>标签<input name="tags" value="'+esc(obj?.tags?.join(',')||'')+'" placeholder="冒烟, Web"></label><label class="full">前置条件<textarea name="precondition">'+esc(obj?.precondition||'')+'</textarea></label><label class="full">步骤 <small>每行：操作 | 预期</small><textarea name="steps" required>'+esc(steps)+'</textarea></label></div><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">保存用例</button></footer></form>';}if(type==='plan'){title='创建测试计划';body='<form data-form="plan"><div class="form-grid"><label>项目<select name="projectId">'+options()+'</select></label><label>版本<input name="version" placeholder="v3.2.1"></label><label class="full">计划名称<input name="name" required></label><div class="full"><span class="field-label">关联用例</span><div class="case-checks">'+state.data.cases.map(c=>'<label><input type="checkbox" name="caseIds" value="'+c.id+'"><span>'+esc(c.title)+'</span><small>'+esc(project(c.projectId))+'</small></label>').join('')+'</div></div></div><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">创建计划</button></footer></form>';}if(type==='execution'){const p=obj||state.data.plans[0];title='执行 · '+(p?.name||'');body=p?'<form data-form="execution" data-id="'+p.id+'">'+p.caseIds.map(id=>'<div class="execution-row"><b>'+esc(state.data.cases.find(c=>c.id===id)?.title||id)+'</b><select name="status-'+id+'"><option value="passed">通过</option><option value="failed">失败</option><option value="blocked">阻塞</option></select><input name="note-'+id+'" placeholder="执行备注"></div>').join('')+'<footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">提交结果</button></footer></form>':'暂无计划';}if(type==='defect'){title=obj?'更新缺陷':'提交缺陷';body='<form data-form="defect" data-id="'+(obj?.id||'')+'"><div class="form-grid"><label>项目<select name="projectId">'+options(obj?.projectId)+'</select></label><label>处理人<select name="assigneeId"><option value="">未分配</option>'+state.data.users.map(u=>'<option value="'+u.id+'" '+(obj?.assigneeId===u.id?'selected':'')+'>'+esc(u.displayName)+'</option>').join('')+'</select></label><label class="full">标题<input name="title" required value="'+esc(obj?.title||'')+'"></label><label>严重程度<select name="severity"><option value="major">严重</option><option value="normal">一般</option><option value="minor">建议</option></select></label><label>优先级<select name="priority"><option>P0</option><option selected>P1</option><option>P2</option></select></label>'+(obj?'<label>状态<select name="status"><option value="open">待修复</option><option value="in_progress">修复中</option><option value="resolved">已修复</option><option value="verified">已验证</option><option value="closed">已关闭</option></select></label>':'')+'<label class="full">描述<textarea name="description" required>'+esc(obj?.description||'')+'</textarea></label></div><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">保存缺陷</button></footer></form>';}if(type==='ui'){title=obj?'编辑 UI 脚本':'新建 UI 自动化脚本';body='<form data-form="ui" data-id="'+(obj?.id||'')+'"><div class="form-grid"><label>项目<select name="projectId">'+options(obj?.projectId)+'</select></label><label>运行浏览器<select name="browser"><option>chromium</option><option>firefox</option><option>webkit</option></select></label><label>脚本名称<input name="name" required value="'+esc(obj?.name||'')+'"></label><label>环境<input name="environment" value="'+esc(obj?.environment||'测试环境')+'"></label><label class="full">标签<input name="tags" value="'+esc(obj?.tags?.join(',')||'')+'"></label><label class="full">Playwright 脚本<textarea class="code-input" name="script" required placeholder="import { test, expect } from \'@playwright/test\';">'+esc(obj?.script||'')+'</textarea></label></div><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">保存脚本</button></footer></form>';}if(type==='user'){title='新增用户';body='<form data-form="user"><div class="form-grid"><label>用户名<input name="username" required pattern="[A-Za-z0-9_-]{3,32}" placeholder="3–32 位字母、数字或 _ -"></label><label>显示姓名<input name="displayName" required></label><label>角色<select name="role">'+Object.entries(state.data.roles).map(([key,role])=>'<option value="'+key+'">'+esc(role.name)+'</option>').join('')+'</select></label><label>初始密码<div class="password-field"><input type="password" name="password" required minlength="8"><button type="button" class="eye-btn" data-action="toggle-password" title="显示密码"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.3 12s3.5-6 9.7-6 9.7 6 9.7 6-3.5 6-9.7 6-9.7-6-9.7-6Z"/><circle cx="12" cy="12" r="2.8"/></svg></button></div></label></div><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">创建用户</button></footer></form>';}if(type==='token'){title='创建访问令牌';body='<form data-form="token"><div class="form-grid"><label>令牌名称<input name="name" required placeholder="CI 只读令牌"></label><label>权限级别<select name="level"><option value="read">read · 只读</option><option value="write">write · 写入</option><option value="admin">admin · 管理</option></select></label><label class="full">过期时间 <small>留空表示不过期</small><input name="expiresAt" type="datetime-local"></label><div class="full"><span class="field-label">允许访问项目 <small>不选择表示全部项目</small></span><div class="case-checks">'+state.data.projects.map(p=>'<label><input type="checkbox" name="projectIds" value="'+p.id+'"><span>'+esc(p.name)+'</span></label>').join('')+'</div></div></div><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">生成令牌</button></footer></form>';}if(type==='password'){title=obj?.id===state.data.user.id?'修改自己的密码':'重置用户密码';body='<form data-form="password" data-id="'+obj.id+'"><p class="muted">正在修改：<b>'+esc(obj.displayName)+'（'+esc(obj.username)+'）</b>。保存后该用户所有网页会话和 API Token 将立即失效。</p>'+(obj.id===state.data.user.id?'<label>当前密码<div class="password-field"><input type="password" name="currentPassword" required autocomplete="current-password"><button type="button" class="eye-btn" data-action="toggle-password" aria-label="显示密码" title="显示密码"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.3 12s3.5-6 9.7-6 9.7 6 9.7 6-3.5 6-9.7 6-9.7-6-9.7-6Z"/><circle cx="12" cy="12" r="2.8"/></svg></button></div></label>':'')+'<label>新密码 <small>至少 8 位，建议包含大小写、数字与符号</small><div class="password-field"><input type="password" name="newPassword" required minlength="8" autocomplete="new-password"><button type="button" class="eye-btn" data-action="toggle-password" aria-label="显示密码" title="显示密码"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.3 12s3.5-6 9.7-6 9.7 6 9.7 6-3.5 6-9.7 6-9.7-6-9.7-6Z"/><circle cx="12" cy="12" r="2.8"/></svg></button></div></label><label>确认新密码<div class="password-field"><input type="password" name="confirmPassword" required minlength="8" autocomplete="new-password"><button type="button" class="eye-btn" data-action="toggle-password" aria-label="显示密码" title="显示密码"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.3 12s3.5-6 9.7-6 9.7 6 9.7 6-3.5 6-9.7 6-9.7-6-9.7-6Z"/><circle cx="12" cy="12" r="2.8"/></svg></button></div></label><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">确认修改密码</button></footer></form>';}if(type==='ai-config'){title='添加 AI 模型';body='<form data-form="ai-config"><div class="form-grid"><label>名称<input name="name" required></label><label>提供商<input name="provider" value="OpenAI Compatible"></label><label class="full">Base URL<input name="baseUrl" required placeholder="https://api.openai.com/v1"></label><label>模型<input name="model" required placeholder="gpt-4o-mini"></label><label>API Key<input name="apiKey" type="password" required></label></div><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">安全保存</button></footer></form>';}state.modal='<div class="modal-shade"><section class="modal"><header><div><span class="eyebrow">CONFIGURE</span><h2>'+title+'</h2></div>'+close+'</header>'+body+'</section></div>';render();}
function formData(form){const o={};new FormData(form).forEach((v,k)=>{if(o[k]===undefined)o[k]=v;else o[k]=[].concat(o[k],v)});['memberIds','caseIds','projectIds'].forEach(k=>{const a=[...form.querySelectorAll('[name="'+k+'"]:checked')].map(x=>x.value);if(a.length)o[k]=a;});return o;}
async function submit(form){const d=formData(form),id=form.dataset.id,t=form.dataset.form;try{if(t==='login'){const r=await api('/auth/login',{method:'POST',body:d});state.token=r.token;localStorage.setItem('aith_token',r.token);state.data=await api('/bootstrap');notify('欢迎回来，'+r.user.displayName);return render();}if(t==='project')await api(id?'/projects/'+id:'/projects',{method:id?'PUT':'POST',body:d});if(t==='case'){d.tags=String(d.tags||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean);d.steps=String(d.steps).split('\n').filter(Boolean).map(x=>{const [action,...expect]=x.split('|');return{action:action.trim(),expected:expect.join('|').trim()}});await api(id?'/cases/'+id:'/cases',{method:id?'PUT':'POST',body:d});}if(t==='plan')await api('/plans',{method:'POST',body:d});if(t==='execution'){const p=state.data.plans.find(x=>x.id===id);d.results=p.caseIds.map(cid=>({caseId:cid,status:d['status-'+cid],note:d['note-'+cid]}));await api('/plans/'+id+'/executions',{method:'POST',body:d});}if(t==='defect')await api(id?'/defects/'+id:'/defects',{method:id?'PUT':'POST',body:d});if(t==='ui'){d.tags=String(d.tags||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean);await api(id?'/ui-cases/'+id:'/ui-cases',{method:id?'PUT':'POST',body:d});}if(t==='case-import'){const file=document.querySelector('#case-import-file')?.files?.[0];if(!file)throw new ApiError('请选择 CSV 文件',{code:'import_file_required'});const rows=parseCaseCsv(await file.text());if(rows.length>1000)throw new ApiError('单次最多导入 1000 条测试用例',{code:'import_limit_exceeded'});await api('/cases/import',{method:'POST',body:{rows}});state.modal=null;await refresh();notify('成功导入 '+rows.length+' 条测试用例');return;}if(t==='user')await api('/users',{method:'POST',body:d});if(t==='token'){const r=await api('/access-tokens',{method:'POST',body:d});state.modal='<div class="modal-shade"><section class="modal token-result"><header><div><span class="eyebrow">SAVE NOW</span><h2>令牌已生成</h2></div><button class="icon-btn" data-action="close">×</button></header><p>此密钥仅显示一次，请立即保存。关闭后无法再次查看。</p><code>'+esc(r.token)+'</code><footer><button class="btn glow" data-action="copy-token" data-token="'+esc(r.token)+'">复制并关闭</button></footer></section></div>';await refresh();return;}if(t==='password'){if(d.newPassword!==d.confirmPassword)throw new ApiError('两次输入的新密码不一致',{code:'password_mismatch'});await api('/users/'+id+'/password',{method:'PATCH',body:d});state.modal=null;await refresh();notify('密码已更新；该用户历史会话与 API Token 已失效');return;}if(t==='ai-config')await api('/ai-configs',{method:'POST',body:d});if(t==='ai'){const r=await api('/ai/generate',{method:'POST',body:{...d,task:state.aiTask}});state.aiResult=r.content;return render();}state.modal=null;await refresh();notify('保存成功');}catch(e){state.modal=null;render();const details=Array.isArray(e.details)?' '+e.details.map(x=>'第'+x.row+'行：'+x.message).join('；'):'';notify(e.message+details+' '+(e.requestId?'#'+e.requestId:''),'error');}}
function bind(){document.querySelectorAll('[data-page]').forEach(n=>n.onclick=()=>{state.page=n.dataset.page;state.modal=null;render();});document.querySelectorAll('form[data-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();submit(f)});document.querySelectorAll('[data-action]').forEach(n=>n.onclick=async()=>{const a=n.dataset.action,id=n.dataset.id;if(a==='logout'){localStorage.removeItem('aith_token');state.token=null;state.data=null;return render();}if(a==='close'){state.modal=null;return render();}if(a==='toggle-account-menu'){n.parentElement?.classList.toggle('open');return;}if(a==='toggle-password'){const input=n.parentElement?.querySelector('input');if(input){const show=input.type==='password';input.type=show?'text':'password';n.innerHTML=show?`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18M10.5 6.2A11.7 11.7 0 0 1 12 6c6.2 0 9.7 6 9.7 6a18.6 18.6 0 0 1-3.1 3.7M6.2 6.2C3.8 8.1 2.3 12 2.3 12s3.5 6 9.7 6c1.4 0 2.7-.3 3.8-.8"/><circle cx="12" cy="12" r="2.8"/></svg>`:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.3 12s3.5-6 9.7-6 9.7 6 9.7 6-3.5 6-9.7 6-9.7-6-9.7-6Z"/><circle cx="12" cy="12" r="2.8"/></svg>`;n.title=show?'隐藏密码':'显示密码';n.setAttribute('aria-label',n.title);}return;}if(a==='query-cases'){state.caseQuery=getCaseFilters();render();return;}if(a==='reset-case-query'){state.caseQuery={projectId:'',module:'',caseType:''};render();return;}if(a==='export-cases'){const type=state.caseQuery.caseType||'';const projectId=state.caseQuery.projectId||'';const link=document.createElement('a');link.href='/api/cases/export?caseType='+encodeURIComponent(type)+'&projectId='+encodeURIComponent(projectId);link.click();return;}if(a==='modal')return modal(n.dataset.modal);if(a==='change-password')return modal('password',state.data.users.find(x=>x.id===id));if(a==='edit-project')return modal('project',state.data.projects.find(x=>x.id===id));if(a==='edit-case')return modal('case',state.data.cases.find(x=>x.id===id));if(a==='execute')return modal('execution',state.data.plans.find(x=>x.id===id));if(a==='edit-defect')return modal('defect',state.data.defects.find(x=>x.id===id));if(a==='edit-ui')return modal('ui',state.data.uiCases.find(x=>x.id===id));if(a==='run-ui'){try{await api('/ui-cases/'+id+'/runs',{method:'POST',body:{status:'queued'}});await refresh();notify('任务已加入受控执行队列');}catch(e){notify(e.message,'error')}}if(a==='revoke-token'){if(confirm('确定撤销这个令牌吗？')){try{await api('/access-tokens/'+id,{method:'DELETE'});await refresh();notify('令牌已撤销')}catch(e){notify(e.message,'error')}}}if(a==='copy-token'){navigator.clipboard?.writeText(n.dataset.token);state.modal=null;render();notify('令牌已复制，请存入密码管理器');}if(a==='export'){try{const r=await api('/reports/export',{method:'POST',body:{}});const x=document.createElement('a');x.href=URL.createObjectURL(new Blob([r.html],{type:'text/html'}));x.download=r.filename;x.click();}catch(e){notify(e.message,'error')}}if(a==='ai-task'){state.aiTask=n.dataset.task;state.aiResult='';render();}if(a==='setup-2fa'){try{const r=await api('/auth/2fa/setup',{method:'POST',body:{}});prompt('请将此密钥添加到验证器，随后在账号安全中继续确认：',r.secret)}catch(e){notify(e.message,'error')}}if(a==='disable-2fa'){try{await api('/auth/2fa/disable',{method:'POST',body:{}});await refresh();notify('2FA 已关闭')}catch(e){notify(e.message,'error')}}});
  const importInput=document.querySelector('#case-import-file');if(importInput){const zone=document.querySelector('[data-import-zone]');const setName=()=>{const name=document.querySelector('[data-import-name]');if(name&&importInput.files?.[0])name.textContent='已选择：'+importInput.files[0].name;};importInput.onchange=setName;if(zone){zone.ondragover=(event)=>{event.preventDefault();zone.classList.add('dragging');};zone.ondragleave=()=>zone.classList.remove('dragging');zone.ondrop=(event)=>{event.preventDefault();zone.classList.remove('dragging');if(event.dataTransfer.files?.[0]){const transfer=new DataTransfer();transfer.items.add(event.dataTransfer.files[0]);importInput.files=transfer.files;setName();}};}}
}
function parseCaseCsv(text){const source=text.replace(/^\uFEFF/,'');const records=[];let row=[],cell='',quoted=false;for(let i=0;i<source.length;i++){const ch=source[i];if(ch==='"'){if(quoted&&source[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&source[i+1]==='\n')i++;row.push(cell);if(row.some(value=>value!==''))records.push(row);row=[];cell='';}else cell+=ch;}if(cell||row.length){row.push(cell);records.push(row);}if(!records.length)return[];const header=records.shift().map(x=>x.trim());const needed=['title','projectId','module','caseType','priority','tags','precondition','steps'];if(!needed.every(x=>header.includes(x)))throw new Error('CSV 表头必须包含：'+needed.join(', '));return records.filter(row=>row.some(value=>value.trim())).map(row=>Object.fromEntries(header.map((name,index)=>[name,row[index]||''])));}
function excelImportModal(){const types=['functional','api','ui','performance','security','compatibility'];state.modal='<div class="modal-shade"><section class="modal"><header><div><span class="eyebrow">EXCEL IMPORT</span><h2>导入 Excel 测试用例</h2></div><button class="icon-btn" data-action="close">×</button></header><form data-form="excel-import"><div class="import-guide"><div><b>Excel 导入规范</b><ul><li>支持 .xlsx、.xls、CSV；单次最多 <strong>1000</strong> 条</li><li>导入前必须选择归属项目，Token 需要有该项目写权限</li><li>多步用例可在步骤、预期结果单元格中换行，一一对应</li></ul></div><button class="link" type="button" data-action="download-template">下载格式化 Excel 模板</button></div><div class="form-grid import-options"><label>导入项目<select name="projectId" required>'+options()+'</select></label><label>默认用例类型<select name="caseType">'+types.map(t=>'<option value="'+t+'">'+caseTypeName(t)+'</option>').join('')+'</select></label></div><div class="field-list"><b>Excel 表头（与您提供的格式一致）</b><code>用例编号, 业务模块, 是否冒烟, 用例标题, 优先级, 前置准备, 步骤, 预期结果, 执行结果</code><small>必填：业务模块、用例标题、优先级、步骤、预期结果；“是否冒烟”填 是 / 否。</small></div><label class="import-dropzone" data-import-zone><input id="case-import-file" type="file" accept=".xlsx,.xls,.csv,text/csv" required><span class="upload-icon">⇧</span><b>点击或拖拽上传 Excel / CSV 文件</b><small data-import-name>请选择不超过 6MB 的文件，最多 1000 条记录</small></label><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">校验并导入</button></footer></form></section></div>';render();}
function parseChineseCaseCsv(text){const source=text.replace(/^\uFEFF/,'');const records=[];let row=[],cell='',quoted=false;for(let i=0;i<source.length;i++){const ch=source[i];if(ch==='"'){if(quoted&&source[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&source[i+1]==='\n')i++;row.push(cell);if(row.some(value=>value!==''))records.push(row);row=[];cell='';}else cell+=ch;}if(cell||row.length){row.push(cell);records.push(row);}const header=(records.shift()||[]).map(x=>x.trim());const needed=['用例编号','业务模块','是否冒烟','用例标题','优先级','前置准备','步骤','预期结果','执行结果'];if(!needed.every(x=>header.includes(x)))throw new Error('Excel / CSV 表头必须包含：'+needed.join('、'));return records.filter(r=>r.some(v=>v.trim())).map(r=>Object.fromEntries(header.map((name,index)=>[name,r[index]||''])));}
async function toBase64(file){return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',').pop());reader.onerror=()=>reject(new Error('文件读取失败'));reader.readAsDataURL(file);});}
async function downloadApi(path, filename){const response=await fetch('/api'+path,{headers:{Authorization:'Bearer '+state.token}});if(!response.ok){const payload=await response.json().catch(()=>({}));throw new ApiError(payload.error?.message||'下载失败',{code:payload.error?.code,requestId:payload.error?.requestId});}const blob=await response.blob(),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),800);}
function excelExportModal(){const types=['functional','api','ui','performance','security','compatibility'];const q=state.caseQuery;state.modal='<div class="modal-shade"><section class="modal export-modal"><header><div><span class="eyebrow">EXCEL EXPORT</span><h2>导出测试用例</h2></div><button class="icon-btn" data-action="close">×</button></header><form data-form="excel-export"><div class="export-banner"><b>选择导出范围</b><span>按项目和用例类型筛选后生成标准 Excel 文件。</span></div><div class="form-grid"><label>项目范围<select name="projectId"><option value="">全部有权限项目</option>'+state.data.projects.map(p=>'<option value="'+p.id+'" '+(q.projectId===p.id?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><label>用例类型<select name="caseType"><option value="">全部类型</option>'+types.map(t=>'<option value="'+t+'" '+(q.caseType===t?'selected':'')+'>'+caseTypeName(t)+'</option>').join('')+'</select></label></div><div class="export-summary"><span>导出格式</span><b>Excel (.xlsx)</b><small>包含格式化表头、列宽、换行、筛选与填写说明页。</small></div><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">确认导出</button></footer></form></section></div>';render();}
const __aithSubmit=submit;submit=async function(form){if(form.dataset.form!=='excel-import')return __aithSubmit(form);try{const d=formData(form),file=document.querySelector('#case-import-file')?.files?.[0];if(!file)throw new ApiError('请选择 Excel 或 CSV 文件');if(file.size>6*1024*1024)throw new ApiError('文件超过 6MB 限制');let result;if(file.name.toLowerCase().endsWith('.csv')){const rows=parseChineseCaseCsv(await file.text());if(rows.length>1000)throw new ApiError('单次最多导入 1000 条测试用例');result=await api('/cases/import',{method:'POST',body:{...d,rows}});}else result=await api('/cases/import-excel',{method:'POST',body:{...d,fileBase64:await toBase64(file)}});state.modal=null;await refresh();notify('成功导入 '+result.imported+' 条测试用例');}catch(e){state.modal=null;render();const details=Array.isArray(e.details)?' '+e.details.map(x=>x.row?'第'+x.row+'行：'+x.message:e.message).join('；'):'';notify(e.message+details,'error');}};
