const __aithSubmitDebounced=submit;submit=async function(form){if(form.dataset.submitting==='1')return;form.dataset.submitting='1';const submitButton=form.querySelector('button[type=submit],button:not([type])');if(submitButton)submitButton.disabled=true;try{return await __aithSubmitDebounced(form);}finally{form.dataset.submitting='0';if(submitButton&&document.contains(submitButton))submitButton.disabled=false;}};
