const __aithPasswordModal=modal;modal=function(type,obj){if(type!=='password')return __aithPasswordModal(type,obj);const self=obj?.id===state.data.user.id;const title=self?'修改自己的密码':'管理员重置用户密码';const current=self?'<label>当前密码<div class="password-field"><input type="password" name="currentPassword" required autocomplete="current-password"></div></label>':'';const hint=self?'修改自己的密码需验证当前密码。':'管理员重置其他用户密码，不需要输入该用户的原密码。';state.modal='<div class="modal-shade"><section class="modal"><header><div><span class="eyebrow">PASSWORD SECURITY</span><h2>'+title+'</h2></div><button class="icon-btn" data-action="close">×</button></header><form data-form="admin-password-reset" data-id="'+esc(obj.id)+'" data-self="'+(self?'true':'false')+'"><p class="hint"><b>'+esc(obj.displayName)+'（'+esc(obj.username)+'）</b><br>'+hint+' 保存后目标用户会被强制退出；其历史网页登录会话和 API Token 会立即失效。</p>'+current+'<label>新密码 <small>至少 8 位</small><input type="password" name="newPassword" required minlength="8" autocomplete="new-password"></label><label>确认新密码<input type="password" name="confirmPassword" required minlength="8" autocomplete="new-password"></label><footer><button type="button" class="btn ghost" data-action="close">取消</button><button class="btn glow">确认重置并强制退出</button></footer></form></section></div>';render();};
